SELECT d.*, c.name AS category_name
FROM dish d
LEFT JOIN category c ON d.category_id = c.id AND c.shop_id = d.shop_id


        AND d.shop_id = #{shopId}


        AND d.category_id = #{categoryId}


        AND d.name LIKE CONCAT('%', #{keyword}, '%')


        AND d.status = #{status}


        AND d.is_del = #{isDel}


ORDER BY d.is_hot DESC, d.sort ASC, d.create_time DESC

SELECT d.*, c.name AS category_name
FROM dish d
LEFT JOIN category c ON d.category_id = c.id AND c.shop_id = d.shop_id


        AND d.shop_id = #{shopId}


        AND d.category_id = #{categoryId}


        AND d.name LIKE CONCAT('%', #{keyword}, '%')


        AND d.status = #{status}


        AND d.is_hot = #{isHot}


        AND d.is_del = #{isDel}


ORDER BY d.is_del ASC, d.status DESC, d.is_hot DESC, d.sort ASC, d.create_time DESC

SELECT d.*, c.name AS category_name
FROM dish d
LEFT JOIN category c ON d.category_id = c.id AND c.shop_id = d.shop_id


        AND d.shop_id = #{shopId}


        AND d.category_id = #{categoryId}


        AND d.status = #{status}

    AND d.is_del = #{isDel}

ORDER BY d.sales DESC, d.is_hot DESC, d.create_time DESC

SELECT d.category_id AS id, c.name AS name, COUNT(1) AS total, SUM(CASE WHEN d.status = 1 THEN 1 ELSE 0 END) AS onShelf FROM dish d LEFT JOIN category c ON d.category_id = c.id AND c.shop_id = d.shop_id
AND d.shop_id = #{shopId}
AND d.is_del = #{isDel}
GROUP BY d.category_id, c.name
